update known_safe_harbors set evidence_summary = 'Direct comparison of 3 loci in HEK293 cells: of AAVS1, CCR5, and human ROSA26 tested for eGFP expression, AAVS1 had the highest and most homogeneous expression of the three. Expression at AAVS1 sustained ~3 months without selection. Within AAVS1 itself, promoter ranking: CMV > EF1a > SV40 > TK.', stability = 'Sustained ~3 months without selection; best of 3 loci compared' where source_pmid = '32470292' and evidence_summary = 'Comparação direta a 3 loci em células HEK293: de AAVS1, CCR5 e ROSA26 humano testados para expressão de eGFP, AAVS1 teve a expressão mais alta e mais homogénea dos três. Expressão em AAVS1 sustentada ~3 meses sem seleção. Dentro do próprio locus AAVS1, ranking de promotores: CMV > EF1a > SV40 > TK.';
