update known_safe_harbors set locus_name = 'Chr1-eGSH', evidence_summary = 'Extragenic candidate locus on chromosome 1. Important cautionary finding: the locus itself allowed robust transgene expression, BUT a gene 2Mb away, within the same topologically associated domain (TAD), showed aberrant expression -- despite the distance, 3D TAD organization propagated the effect. The authors conclude Chr1-eGSH is not suitable for therapeutic gene integration despite the locus itself appearing good. Also tested with a suicide-gene safety system (HSV-TK/ganciclovir): sensitive in vitro, but resulting teratomas showed variable degrees of resistance in vivo -- the safety system itself is not reliably guaranteed.', stability = 'Locus itself stable, but distal TAD effect makes it unsuitable' where source_pmid = '30887735' and evidence_summary = 'Locus candidato extragénico no cromossoma 1. Achado importante e cautelar: o próprio locus permitiu expressão robusta do transgene, MAS um gene a 2Mb de distância, dentro do mesmo domínio topologicamente associado (TAD), mostrou expressão aberrante -- apesar da distância, a organização 3D do TAD propagou o efeito. Os autores concluem que Chr1-eGSH não é adequado para integração génica terapêutica apesar de o locus em si parecer bom. Também testado com sistema de segurança de gene suicida (HSV-TK/ganciclovir): sensível in vitro, mas teratomas resultantes mostraram graus variáveis de resistência in vivo -- o próprio sistema de segurança não é garantidamente fiável.';
update public_safe_harbors_staging set locus_name = 'Chr1-eGSH', evidence_summary = 'Extragenic candidate locus on chromosome 1. Important cautionary finding: the locus itself allowed robust transgene expression, BUT a gene 2Mb away, within the same topologically associated domain (TAD), showed aberrant expression -- despite the distance, 3D TAD organization propagated the effect. The authors conclude Chr1-eGSH is not suitable for therapeutic gene integration despite the locus itself appearing good. Also tested with a suicide-gene safety system (HSV-TK/ganciclovir): sensitive in vitro, but resulting teratomas showed variable degrees of resistance in vivo -- the safety system itself is not reliably guaranteed.', stability = 'Locus itself stable, but distal TAD effect makes it unsuitable' where source_pmid = '30887735' and evidence_summary = 'Locus candidato extragénico no cromossoma 1. Achado importante e cautelar: o próprio locus permitiu expressão robusta do transgene, MAS um gene a 2Mb de distância, dentro do mesmo domínio topologicamente associado (TAD), mostrou expressão aberrante -- apesar da distância, a organização 3D do TAD propagou o efeito. Os autores concluem que Chr1-eGSH não é adequado para integração génica terapêutica apesar de o locus em si parecer bom. Também testado com sistema de segurança de gene suicida (HSV-TK/ganciclovir): sensível in vitro, mas teratomas resultantes mostraram graus variáveis de resistência in vivo -- o próprio sistema de segurança não é garantidamente fiável.';

update known_safe_harbors set evidence_summary = 'Doxycycline-inducible Cas9 confirmed single-copy integrated at AAVS1, in iPSC derived from fetal liver B progenitors. Pluripotency maintained after editing. Robust, specific Cas9 expression after induction, functional gene editing confirmed by T7 endonuclease assay.', stability = 'Pluripotency maintained after editing (duration not further quantified)' where source_pmid = '28677529' and evidence_summary = 'Cas9 indutível por doxiciclina integrado em cópia única confirmada em AAVS1, em iPSC derivada de progenitores B de fígado fetal. Pluripotência mantida após edição. Expressão robusta e específica de Cas9 após indução, edição génica funcional confirmada por ensaio T7-endonuclease.';
