update known_safe_harbors set evidence_summary = 'Founding paper (2010): ZFN targets PPP1R12C (AAVS1) without drug selection, transgenesis efficiency up to 15% in transient transfection, in transformed AND primary cells (fibroblasts, hES). Transgenes (shRNA, small-molecule-responsive cassettes, reporters) show consistent expression and sustained function for over 50 cell generations -- classic reference for "AAVS1 holds up over many generations".', stability = 'Sustained function for >50 cell generations' where source_pmid = '20508142' and evidence_summary = 'Paper fundador (2010): ZFN alveja PPP1R12C (AAVS1) sem seleção por fármaco, eficiência de transgénese até 15% em transfeção transitória, em células transformadas E primárias (fibroblastos, hES). Transgenes (shRNA, cassetes responsivas a pequenas moléculas, repórteres) mostram expressão consistente e função sustentada por mais de 50 gerações celulares -- referência clássica para "AAVS1 aguenta muitas gerações".';
update public_safe_harbors_staging set evidence_summary = 'Founding paper (2010): ZFN targets PPP1R12C (AAVS1) without drug selection, transgenesis efficiency up to 15% in transient transfection, in transformed AND primary cells (fibroblasts, hES). Transgenes (shRNA, small-molecule-responsive cassettes, reporters) show consistent expression and sustained function for over 50 cell generations -- classic reference for "AAVS1 holds up over many generations".', stability = 'Sustained function for >50 cell generations' where source_pmid = '20508142' and evidence_summary = 'Paper fundador (2010): ZFN alveja PPP1R12C (AAVS1) sem seleção por fármaco, eficiência de transgénese até 15% em transfeção transitória, em células transformadas E primárias (fibroblastos, hES). Transgenes (shRNA, cassetes responsivas a pequenas moléculas, repórteres) mostram expressão consistente e função sustentada por mais de 50 gerações celulares -- referência clássica para "AAVS1 aguenta muitas gerações".';

update known_safe_harbors set evidence_summary = 'Human HPRT locus (KhES-1 hES line) targeted via homologous recombination + Cre-recombinase site-specific integration. Tetracycline/doxycycline-responsive inducible reporter system, with self-renewal and pluripotency maintained. Confirms in human the same type of locus already validated in mouse (Hprt1) in earlier batches.', stability = 'Self-renewal and pluripotency maintained (duration not further quantified)' where source_pmid = '20071742' and evidence_summary = 'Locus HPRT humano (linha hES KhES-1) alvejado por recombinação homóloga + integração sítio-específica por recombinase Cre. Sistema repórter indutível por tetraciclina responsivo a doxiciclina, com auto-renovação e pluripotência mantidas. Confirma em humano o mesmo tipo de locus já validado em ratinho (Hprt1) nos lotes anteriores.';
