update known_safe_harbors set evidence_summary = 'Voltage indicator (VSFP, FRET) under the CAG promoter stably expressed at AAVS1 in hiPSC-CM (cardiomyocytes). Functionally validated in ventricular, atrial, and nodal subtypes, in 2D monolayers and in 3D context, with high-throughput optical action-potential recordings.', stability = 'Stable expression validated across cardiomyocyte subtypes' where source_pmid = '36274846' and evidence_summary = 'Indicador de voltagem (VSFP, FRET) sob promotor CAG estavelmente expresso em AAVS1 em hiPSC-CM (cardiomiócitos). Validado funcionalmente em subtipos ventricular, atrial e nodal, em monocamadas 2D e em contexto 3D, com gravações óticas de potencial de ação de alto rendimento.';
