update known_safe_harbors set evidence_summary = 'Lysosomal iduronidase enzyme (deficient in Mucopolysaccharidosis type I) targeted to CCR5 in human CD34+ hematopoietic stem cells. Enzyme secretion above normal endogenous level, long-term repopulation capacity and multi-lineage differentiation maintained, improvement of biochemical/phenotypic abnormalities in an immunocompromised mouse model of the disease.', stability = 'Long-term repopulation capacity maintained in vivo' where source_pmid = '31492863' and evidence_summary = 'Enzima lisossomal iduronidase (défice na Mucopolissacaridose tipo I) alvejada a CCR5 em células estaminais hematopoiéticas CD34+ humanas. Secreção de enzima acima do nível endógeno normal, capacidade de repovoamento a longo prazo e diferenciação multi-linhagem mantida, melhoria de anomalias bioquímicas/fenotípicas em modelo murino imunocomprometido da doença.';
