update known_safe_harbors set evidence_summary = 'Full-length F9 cDNA (factor IX) inserted at AAVS1 in iPSC from a hemophilia B patient. No off-target mutations detected by whole-genome sequencing. Derived hepatocytes stably secreted hFIX and survived short-term transplant in NOD/SCID mice.', stability = 'Stable secretion through short-term transplant survival' where source_pmid = '29625575' and evidence_summary = 'cDNA F9 completo (fator IX) inserido em AAVS1 em iPSC de doente com hemofilia B. Sem mutações off-target detetadas por sequenciação do genoma completo. Hepatócitos derivados secretaram hFIX de forma estável e sobreviveram a transplante de curto prazo em ratinhos NOD/SCID.';
