update known_safe_harbors set evidence_summary = 'hFIX inserted at AAVS1 in human mesenchymal stem cells (MSCs) -- a novel cell context compared to other records. Stem cell traits maintained after integration; hFIX effectively expressed in vivo and in vitro, with no significant expression differences between individual clones.', stability = 'Stable, consistent expression across clones' where source_pmid = '28112377' and evidence_summary = 'hFIX inserido em AAVS1 em células estaminais mesenquimais (MSC) humanas -- contexto celular novo face aos restantes registos. Traços de célula estaminal mantidos após integração; hFIX expresso eficazmente in vivo e in vitro, sem diferenças significativas de expressão entre clones individuais.';
update public_safe_harbors_staging set evidence_summary = 'hFIX inserted at AAVS1 in human mesenchymal stem cells (MSCs) -- a novel cell context compared to other records. Stem cell traits maintained after integration; hFIX effectively expressed in vivo and in vitro, with no significant expression differences between individual clones.', stability = 'Stable, consistent expression across clones' where source_pmid = '28112377' and evidence_summary = 'hFIX inserido em AAVS1 em células estaminais mesenquimais (MSC) humanas -- contexto celular novo face aos restantes registos. Traços de célula estaminal mantidos após integração; hFIX expresso eficazmente in vivo e in vitro, sem diferenças significativas de expressão entre clones individuais.';

update known_safe_harbors set evidence_summary = 'Targeted integration in human CD34+ HSPCs: up to 58% Venus+ cells with 6-16% human cell engraftment marking in mice. In HSPCs from X-linked chronic granulomatous disease patients, gp91phox transgene at AAVS1 gave ~15% expression and increased NADPH oxidase activity in neutrophils ex vivo; in transplanted mice, 4-11% of human cells in bone marrow expressed gp91phox -- moderate but carefully quantified efficiency.', stability = 'Detectable engraftment and expression in vivo (moderate efficiency)' where source_pmid = '26950749' and evidence_summary = 'Integração alvejada em CD34+ HSPCs humanas: até 58% de células Venus+ com 6-16% de marcação de células humanas após enxerto em ratinhos. Em HSPCs de doentes com doença granulomatosa crónica ligada ao X, transgene gp91phox em AAVS1 deu ~15% de expressão e atividade NADPH oxidase aumentada em neutrófilos ex vivo; em ratinhos transplantados, 4-11% das células humanas na medula óssea expressaram gp91phox -- eficiência moderada mas quantificada em detalhe.';
update public_safe_harbors_staging set evidence_summary = 'Targeted integration in human CD34+ HSPCs: up to 58% Venus+ cells with 6-16% human cell engraftment marking in mice. In HSPCs from X-linked chronic granulomatous disease patients, gp91phox transgene at AAVS1 gave ~15% expression and increased NADPH oxidase activity in neutrophils ex vivo; in transplanted mice, 4-11% of human cells in bone marrow expressed gp91phox -- moderate but carefully quantified efficiency.', stability = 'Detectable engraftment and expression in vivo (moderate efficiency)' where source_pmid = '26950749' and evidence_summary = 'Integração alvejada em CD34+ HSPCs humanas: até 58% de células Venus+ com 6-16% de marcação de células humanas após enxerto em ratinhos. Em HSPCs de doentes com doença granulomatosa crónica ligada ao X, transgene gp91phox em AAVS1 deu ~15% de expressão e atividade NADPH oxidase aumentada em neutrófilos ex vivo; em ratinhos transplantados, 4-11% das células humanas na medula óssea expressaram gp91phox -- eficiência moderada mas quantificada em detalhe.';

update known_safe_harbors set evidence_summary = 'Founding paper (2009): transgene inserted at AAVS1 in hESC to create a robust, drug-inducible overexpression system -- one of the first documented uses of AAVS1 for this purpose, alongside OCT4 and PITX3 reporters (target genes, not safe harbors).', stability = 'Robust, inducible system (duration not further quantified)' where source_pmid = '19680244' and evidence_summary = 'Paper fundador (2009): transgene inserido em AAVS1 em hESC para criar sistema de sobre-expressão robusto e indutível por fármaco -- um dos primeiros usos documentados de AAVS1 com este propósito, ao lado de repórteres OCT4 e PITX3 (genes-alvo, não safe harbors).';
update public_safe_harbors_staging set evidence_summary = 'Founding paper (2009): transgene inserted at AAVS1 in hESC to create a robust, drug-inducible overexpression system -- one of the first documented uses of AAVS1 for this purpose, alongside OCT4 and PITX3 reporters (target genes, not safe harbors).', stability = 'Robust, inducible system (duration not further quantified)' where source_pmid = '19680244' and evidence_summary = 'Paper fundador (2009): transgene inserido em AAVS1 em hESC para criar sistema de sobre-expressão robusto e indutível por fármaco -- um dos primeiros usos documentados de AAVS1 com este propósito, ao lado de repórteres OCT4 e PITX3 (genes-alvo, não safe harbors).';

update known_safe_harbors set locus_name = 'Pseudo-attP sites (phiC31 integrase)', evidence_summary = 'A different locus category from AAVS1/ROSA26: endogenous pseudo-attP sites targeted by phiC31 integrase in hESC (not a single named locus, a hotspot profile). GFP under the Oct4 promoter tracked endogenous Oct4 expression (expected, responds to differentiation); GFP under the EF1alpha promoter gave stable, persistent expression. Clones retained differentiation capacity into all 3 germ layers.', stability = 'Stable/persistent under EF1alpha; expected downregulation under Oct4 promoter' where source_pmid = '17962703' and evidence_summary = 'Categoria de locus diferente de AAVS1/ROSA26: sítios pseudo-attP endógenos alvejados pela integrase phiC31 em hESC (não um locus único nomeado, um perfil de pontos quentes de integração). GFP sob promotor Oct4 acompanhou a expressão endógena de Oct4 (esperado, responde a diferenciação); GFP sob promotor EF1alpha deu expressão estável e persistente. Clones mantiveram capacidade de diferenciação nas 3 camadas germinativas.';
